var scene = UnityEngine.SceneManagement.SceneManager.GetSceneByName("City");
if (!scene.IsValid()) { Debug.LogError("City scene not loaded"); return; }
var roots = scene.GetRootGameObjects();
Sim.Jobs.JobCompletionResultPanel comp = null;
foreach (var r in roots) {
    comp = r.GetComponentInChildren<Sim.Jobs.JobCompletionResultPanel>(true);
    if (comp != null) break;
}
if (comp == null) { Debug.LogError("JobCompletionResultPanel not found"); return; }
var modal = comp.transform.Find("Modal");
if (modal == null) { Debug.LogError("Modal child not found on " + comp.name); return; }
var so = new UnityEditor.SerializedObject(comp);
so.Update();
so.FindProperty("root").objectReferenceValue = modal.gameObject;
so.ApplyModifiedProperties();
UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);
Debug.Log("[Wire] root = " + modal.name);
